char *printBin(double num) {
  char *res = (char *)malloc(40);
  strcpy(res, "0.");
  int len = 2;
  while (num > 0 && len < 32) {
    num *= 2;
    if (num >= 1) {
      res[len++] = '1';
      num -= 1;
    } else {
      res[len++] = '0';
    }
  }
  res[len] = '\0';
  if (num > 0) strcpy(res, "ERROR");
  return res;
}

class Solution {
public:
  string printBin(double num) {
    string res = "0.";
    while (num > 0 && res.size() < 32) {
      num *= 2;
      if (num >= 1) {
        res += '1';
        num -= 1;
      } else {
        res += '0';
      }
    }
    return num > 0 ? "ERROR" : res;
  }
};

